const r=await tools.exec_command({cmd:"python3 - <<'PY'
import io,json,tarfile,urllib.request
url='https://registry.npmjs.org/alchemy/-/alchemy-2.0.0-beta.80.tgz'
raw=urllib.request.urlopen(url,timeout=30).read(); archive=tarfile.open(fileobj=io.BytesIO(raw),mode='r:gz')
need=['/src/Secrets/','/src/Doppler/','/src/Stack.ts','/src/Runtime.ts']
for m in archive.getmembers():
 if m.isfile() and any(x in m.name for x in need):
  data=archive.extractfile(m).read().decode('utf8')
  if m.name.endswith('/index.ts') or m.name.endswith('/Secrets.ts') or m.name.endswith('/Auth.ts'):
   print('FILE '+m.name+'\n'+data[:35000])
  elif m.name.endswith('/Stack.ts'):
   ls=data.splitlines(); print('FILE '+m.name)
   for i,line in enumerate(ls):
    if any(k in line for k in ['secrets?:','SecretProvider','ProcessEnv','secrets:','ConfigProvider','envFile']):
     print('\n'.join(str(j+1)+': '+ls[j] for j in range(max(0,i-3),min(len(ls),i+7))))
  else:
   print('AVAILABLE '+m.name)
