import json,pathlib,subprocess,collections
root=pathlib.Path('/Users/cooper/Projects/taxkit'); names=collections.defaultdict(list); files=subprocess.check_output(['rg','--files','-g','package.json','-g','!**/node_modules/**','-g','!**/.source/**','-g','!**/dist/**'],cwd=root,text=True).splitlines()
for f in files:
 p=json.loads((root/f).read_text())
 for section in ['dependencies','devDependencies','peerDependencies','optionalDependencies']:
  for n,s in p.get(section,{}).items():
   if not s.startswith('workspace:'): names[n].append([f,section,s])
 for n,s in p.get('workspaces',{}).get('catalog',{}).items(): names[n].append([f,'catalog',s])
 for n,s in p.get('overrides',{}).items(): names[n].append([f,'override',s])
for n in sorted(names):print(json.dumps({'name':n,'requirements':names[n]}))
print('COUNTS '+str(len(files))+' manifests '+str(len(names))+' external dependencies')
PY

