import * as Schema from "effect/Schema";

// The capture key is public and write-only. Management credentials never enter this contract.
export const CaptureKey = Schema.String.check(
  Schema.isPattern(/^phc_[A-Za-z0-9_-]{20,200}$/u),
).pipe(Schema.brand("CaptureKey"));
export const AnalyticsStage = Schema.String.check(
  Schema.isPattern(/^(?:dev|preview|integration|production|pr-[1-9][0-9]{0,6})$/u),
).pipe(Schema.brand("AnalyticsStage"));
export const CaptureConfig = Schema.Union([
  Schema.TaggedStruct("AnalyticsDisabled", {}),
  Schema.TaggedStruct("AnalyticsEnabled", {
    key: CaptureKey,
    host: Schema.Literal("https://us.i.posthog.com"),
    environment: Schema.Literals(["production", "test"]),
    stage: AnalyticsStage,
  }).check(
    Schema.makeFilter(
      (value) =>
        (value.stage === "production" && value.environment === "production") ||
        (value.stage !== "production" && value.stage !== "dev" && value.environment === "test"),
      { message: "Analytics must use the matching production or test project" },
    ),
  ),
]).pipe(Schema.toTaggedUnion("_tag"));
export type CaptureConfig = typeof CaptureConfig.Type;
export const CaptureConfigJson = Schema.fromJsonString(CaptureConfig);
// Browser delivery stays on the matching Website; backend delivery keeps its own host.
export const BrowserCapturePath = Schema.Literal("/ingest").pipe(
  Schema.brand("BrowserCapturePath"),
);
export const browserCapturePath = BrowserCapturePath.make("/ingest");
export const disabledAnalytics = CaptureConfig.cases.AnalyticsDisabled.make({});
export const CaptureBinding = Schema.Struct({ stage: AnalyticsStage, config: CaptureConfig }).check(
  Schema.makeFilter(
    (value) =>
      Schema.is(CaptureConfig.cases.AnalyticsDisabled)(value.config) ||
      value.stage === value.config.stage,
    { message: "Capture configuration must match this Worker's stage" },
  ),
);
export const PageName = Schema.Literals(["home", "about", "not-found"]);
export const PageView = Schema.Struct({ page: PageName });
export type PageView = typeof PageView.Type;
export const NavigationUse = Schema.Struct({
  action: Schema.Literals(["home-navigation", "about-navigation", "return-home"]),
});
export type NavigationUse = typeof NavigationUse.Type;
export const ReferrerHost = Schema.String.check(
  Schema.isPattern(/^(?:direct|unknown|[a-z0-9.-]{1,253})$/u),
).pipe(Schema.brand("ReferrerHost"));
export const CampaignName = Schema.String.check(Schema.isPattern(/^[A-Za-z0-9_-]{1,64}$/u)).pipe(
  Schema.brand("CampaignName"),
);
export const VisitorId = Schema.String.check(Schema.isPattern(/^[A-Za-z0-9._:-]{1,200}$/u)).pipe(
  Schema.brand("VisitorId"),
);
export const ApiRequestId = Schema.String.check(
  Schema.isPattern(/^api:-?[0-9]+:-?[0-9]+$/u),
  Schema.isMaxLength(64),
).pipe(Schema.brand("ApiRequestId"));
export type ApiRequestId = typeof ApiRequestId.Type;
export const ApiProtocol = Schema.Literals(["http", "rpc", "mcp", "publishing", "other"]);
export type ApiProtocol = typeof ApiProtocol.Type;
export const ApiOutcome = Schema.Literals(["success", "failure", "interrupted"]);
export const ApiStatusCode = Schema.Int.check(
  Schema.isBetween({ minimum: 100, maximum: 599 }),
).pipe(Schema.brand("ApiStatusCode"));
export const DurationMs = Schema.Finite.check(Schema.isGreaterThanOrEqualTo(0)).pipe(
  Schema.brand("AnalyticsDurationMs"),
);
export const ApiUse = Schema.Union([
  Schema.TaggedStruct("ApiRequestCompleted", {
    protocol: ApiProtocol,
    method: Schema.Literals([
      "GET",
      "HEAD",
      "POST",
      "PUT",
      "PATCH",
      "DELETE",
      "OPTIONS",
      "TRACE",
      "CONNECT",
      "QUERY",
    ]),
    status: ApiStatusCode,
    durationMs: DurationMs,
  }),
  Schema.TaggedStruct("ContentReadCompleted", {
    protocol: ApiProtocol,
    operation: Schema.Literals(["listPages", "getPage"]),
    page: Schema.Literals(["home", "about", "other", "none"]),
    format: Schema.Literals(["data", "markdown", "seo", "og", "none"]),
    outcome: ApiOutcome,
  }),
]).pipe(Schema.toTaggedUnion("_tag"));
export type ApiUse = typeof ApiUse.Type;
export const ApiUseBatch = Schema.Struct({
  requestId: ApiRequestId,
  events: Schema.Array(ApiUse).check(Schema.isMaxLength(65)),
});
export type ApiUseBatch = typeof ApiUseBatch.Type;

