import {
  AnalyticsStage,
  CampaignName,
  CaptureKey,
  NavigationUse,
  PageView,
  ReferrerHost,
  VisitorId,
} from "@common-practice/analytics/schemas";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";
import type { CaptureResult } from "posthog-js";

export const BrowserSource = Schema.Struct({
  referrerHost: ReferrerHost,
  campaignSource: Schema.optionalKey(CampaignName),
  campaignMedium: Schema.optionalKey(CampaignName),
  campaignName: Schema.optionalKey(CampaignName),
});
const properties = {
  ...BrowserSource.fields,
  // The browser SDK requires this public project key in each capture event.
  token: CaptureKey,
  distinct_id: VisitorId,
  environment: Schema.Literals(["production", "test"]),
  stage: AnalyticsStage,
  $process_person_profile: Schema.Literal(false),
  $geoip_disable: Schema.Literal(true),
};
const envelope = {
  uuid: Schema.String.check(Schema.isUUID()).pipe(Schema.brand("BrowserCaptureId")),
  timestamp: Schema.optionalKey(Schema.Date),
};
const BrowserCapture = Schema.Union([
  Schema.Struct({
    ...envelope,
    event: Schema.Literal("common_practice_page_viewed"),
    properties: Schema.Struct({ ...properties, ...PageView.fields }),
  }),
  Schema.Struct({
    ...envelope,
    event: Schema.Literal("common_practice_navigation_used"),
    properties: Schema.Struct({ ...properties, ...NavigationUse.fields }),
  }),
]);

// The SDK requires a synchronous nullable callback. This exact consumer uses a
// non-throwing Schema decoder and copies only our allowlist. Extra SDK fields,
// full URLs, page text, session IDs and person properties cannot leave this callback.
export const sanitiseBrowserCapture = (input: CaptureResult | null): CaptureResult | null =>
  Schema.decodeUnknownOption(BrowserCapture)(input).pipe(
    Option.match({
      onNone: () => null,
      onSome: (value) => value,
    }),
  );
