import {
  AnalyticsStage,
  CaptureConfig,
  CaptureConfigJson,
  disabledAnalytics,
} from "@common-practice/analytics/schemas";
import { PostHogProject } from "./resources";
import type { DeploymentStage } from "../schemas";
import * as Output from "alchemy/Output";
import { packEnvValueKeepRedacted } from "alchemy/RuntimeContext";
import * as Config from "effect/Config";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import * as Schema from "effect/Schema";
import * as Boolean from "effect/Boolean";
import { pipe } from "effect/Function";

export const commonPracticePostHogBindings = Effect.fn("PostHog.commonPracticeBindings")(
  function* ({ stage }: Readonly<{ stage: DeploymentStage }>) {
    const test = yield* Config.Boolean("COMMON_PRACTICE_POSTHOG_TEST").pipe(
      Config.withDefault(false),
      Effect.orDie,
    );
    if (stage === "dev" || (stage !== "production" && !test)) {
      const encoded = yield* Schema.encodeEffect(CaptureConfigJson)(disabledAnalytics).pipe(
        Effect.orDie,
      );
      return {
        COMMON_PRACTICE_POSTHOG_CONFIG: pipe(
          encoded,
          Redacted.make,
          packEnvValueKeepRedacted,
          Output.asOutput,
        ),
      };
    }
    const production = stage === "production";
    const environment = Boolean.match(production, {
      onTrue: (): "production" => "production",
      onFalse: (): "test" => "test",
    });
    const logicalId = Boolean.match(production, {
      onTrue: () => "ProductionProject",
      onFalse: () => "TestProject",
    });
    const project = yield* PostHogProject.ref(logicalId, {
      stack: "daw-analytics",
      stage: "production",
    });
    return {
      COMMON_PRACTICE_POSTHOG_CONFIG: project.key.pipe(
        Output.mapEffect((key) =>
          Schema.encodeEffect(CaptureConfigJson)(
            CaptureConfig.cases.AnalyticsEnabled.make({
              key: Redacted.value(key),
              host: "https://us.i.posthog.com",
              environment,
              stage: AnalyticsStage.make(stage),
            }),
          ).pipe(
            // These are explicit env props. Pack the native Redacted marker so
            // Alchemy's runtime get returns the JSON string to Config.schema,
            // rather than parsing it into an object before the JSON codec runs.
            Effect.map(Redacted.make),
            Effect.map(packEnvValueKeepRedacted),
            Effect.orDie,
          ),
        ),
      ),
    };
  },
);
import { postHogDashboards } from "@common-practice/infrastructure/posthog/dashboards";
import {
  PostHogDashboard,
  PostHogInsight,
  PostHogProject,
  PostHogTile,
  postHogProviders,
} from "@common-practice/infrastructure/posthog/resources";
import {
  ManagedName,
  OrganisationId,
  OwnershipMarker,
} from "@common-practice/infrastructure/posthog/schemas";
import { requireProductionStage } from "@common-practice/infrastructure/stacks/telemetry";
import * as Alchemy from "alchemy";
import * as Cloudflare from "alchemy/Cloudflare";
import { retain } from "alchemy/RemovalPolicy";
import * as Config from "effect/Config";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Match from "effect/Match";

export default Alchemy.Stack(
  "daw-analytics",
  {
    providers: Layer.mergeAll(Cloudflare.providers(), postHogProviders.pipe(Layer.orDie)),
    state: Cloudflare.state(),
  },
  Effect.gen(function* () {
    yield* requireProductionStage;
    const organisation = yield* Config.schema(OrganisationId, "POSTHOG_ORGANIZATION_ID");
    for (const environment of ["production", "test"]) {
      const prefix = Match.value(environment).pipe(
        Match.when("production", () => "Production"),
        Match.orElse(() => "Test"),
      );
      // Keep TestProject and its test markers stable when changing the display name.
      const project = yield* PostHogProject(`${prefix}Project`, {
        organisation,
        name: ManagedName.make(
          Match.value(environment).pipe(
            Match.when("production", () => "Common Practice production"),
            Match.orElse(() => "Common Practice preview"),
          ),
        ),
        marker: OwnershipMarker.make(`common-practice-alchemy:${environment}:Project`),
      }).pipe(retain());
      for (const definition of postHogDashboards) {
        const dashboard = yield* PostHogDashboard(`${prefix}${definition.logicalId}`, {
          project: project.id,
          name: definition.name,
          marker: OwnershipMarker.make(
            `common-practice-alchemy:${environment}:${definition.logicalId}`,
          ),
        });
        for (const chart of definition.insights) {
          const marker = OwnershipMarker.make(
            `common-practice-alchemy:${environment}:${chart.logicalId}`,
          );
          const insight = yield* PostHogInsight(`${prefix}${chart.logicalId}`, {
            project: project.id,
            name: chart.name,
            marker,
            query: { kind: "DataTableNode", source: { kind: "HogQLQuery", query: chart.query } },
          });
          yield* PostHogTile(`${prefix}${chart.logicalId}Tile`, {
            project: project.id,
            insight: insight.id,
            dashboard: dashboard.id,
            marker,
          });
        }
      }
    }
    return { projectCount: 2, dashboardCount: 4, insightCount: 12 };
  }),
);

