import { AnalyticsError } from "@common-practice/analytics/errors";
import {
  CaptureConfig,
  NavigationUse,
  PageView,
  ReferrerHost,
  CampaignName,
  browserCapturePath,
} from "@common-practice/analytics/schemas";
import type { CaptureConfig as CaptureSettings } from "@common-practice/analytics/schemas";
import { BrowserAnalytics } from "@common-practice/analytics/service";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Option from "effect/Option";
import * as Ref from "effect/Ref";
import * as Schema from "effect/Schema";
import * as Semaphore from "effect/Semaphore";
import type { PostHog } from "posthog-js";
import { BrowserSource, sanitiseBrowserCapture } from "./capture.consumer";
import { WebsiteIdentity } from "../webmcp/identity.service";

const CaptureAcknowledgement = Schema.OptionFromUndefinedOr(
  Schema.Struct({
    event: Schema.Literals(["common_practice_page_viewed", "common_practice_navigation_used"]),
  }),
);

export const browserAnalyticsLayer = (settings: CaptureSettings) =>
  Layer.effect(
    BrowserAnalytics,
    Effect.gen(function* () {
      const identity = yield* WebsiteIdentity;
      const config = yield* Schema.decodeEffect(Schema.toType(CaptureConfig))(settings).pipe(
        Effect.option,
      );
      const sameOrigin = yield* Effect.try({
        try: () => window.location.origin === identity.origin && navigator.doNotTrack !== "1",
        catch: () => new AnalyticsError({ operation: "configure", reason: "unavailable" }),
      }).pipe(Effect.orElseSucceed(() => false));
      const enabled =
        Option.exists(config, Schema.is(CaptureConfig.cases.AnalyticsEnabled)) && sameOrigin;
      const client = yield* Ref.make(Option.none<PostHog>());
      const sentPage = yield* Ref.make(Option.none<PageView>());
      const lock = yield* Semaphore.make(1);
      const source = yield* Effect.try({
        try: () => ({ referrer: document.referrer, address: window.location.href }),
        catch: () => new AnalyticsError({ operation: "configure", reason: "unavailable" }),
      }).pipe(
        Effect.flatMap(({ referrer, address }) =>
          Effect.gen(function* () {
            const url = yield* Schema.decodeEffect(Schema.URLFromString)(address);
            const referring = yield* Schema.decodeEffect(Schema.URLFromString)(referrer).pipe(
              Effect.option,
            );
            const campaignSource = yield* Schema.decodeUnknownEffect(CampaignName)(
              url.searchParams.get("utm_source"),
            ).pipe(Effect.option);
            const campaignMedium = yield* Schema.decodeUnknownEffect(CampaignName)(
              url.searchParams.get("utm_medium"),
            ).pipe(Effect.option);
            const campaignName = yield* Schema.decodeUnknownEffect(CampaignName)(
              url.searchParams.get("utm_campaign"),
            ).pipe(Effect.option);
            return yield* Schema.decodeEffect(BrowserSource)({
              referrerHost: Option.match(referring, {
                onNone: () => "direct",
                onSome: (value) => value.hostname,
              }),
              ...Option.match(campaignSource, {
                onNone: () => ({}),
                onSome: (value) => ({ campaignSource: value }),
              }),
              ...Option.match(campaignMedium, {
                onNone: () => ({}),
                onSome: (value) => ({ campaignMedium: value }),
              }),
              ...Option.match(campaignName, {
                onNone: () => ({}),
                onSome: (value) => ({ campaignName: value }),
              }),
            });
          }),
        ),
        Effect.orElseSucceed(() => ({ referrerHost: ReferrerHost.make("unknown") })),
      );

      const stop = Effect.fnUntraced(function* () {
        const active = yield* Ref.getAndSet(client, Option.none());
        yield* Ref.set(sentPage, Option.none());
        if (Option.isNone(active)) {
          return;
        }
        // The browser SDK's public shutdown contract is Promise<void>. This exact
        // adapter owns that bridge; Effect Scope closes it on Atom unmount.
        yield* Effect.tryPromise({
          try: () => active.value.shutdown(),
          catch: () => new AnalyticsError({ operation: "shutdown", reason: "unavailable" }),
        }).pipe(Effect.timeout("2 seconds"), Effect.ignore);
      });
      yield* Effect.addFinalizer(stop);
      yield* Effect.gen(function* () {
        if (!enabled || Option.isNone(config)) {
          return;
        }
        const capture = config.value;
        if (!Schema.is(CaptureConfig.cases.AnalyticsEnabled)(capture)) {
          return;
        }
        // The removed Common Practice choice does not control capture. Clean its old key
        // without depending on browser storage being available.
        yield* Effect.try({
          try: () => {
            window.localStorage.removeItem("daw.analytics.consent.v1");
          },
          catch: () => new AnalyticsError({ operation: "configure", reason: "unavailable" }),
        }).pipe(Effect.ignore);
        const sdk = yield* Effect.tryPromise({
          try: () => import("posthog-js"),
          catch: () => new AnalyticsError({ operation: "configure", reason: "unavailable" }),
        }).pipe(
          Effect.timeoutOrElse({
            duration: "5 seconds",
            orElse: () =>
              Effect.fail(new AnalyticsError({ operation: "configure", reason: "timeout" })),
          }),
        );
        const active = yield* Effect.try({
          try: () => new sdk.PostHog(),
          catch: () => new AnalyticsError({ operation: "configure", reason: "unavailable" }),
        });
        // Scope owns the instance before init, so a partial init is still closed.
        yield* Ref.set(client, Option.some(active));
        yield* Effect.try({
          try: () => {
            active.init(capture.key, {
              api_host: browserCapturePath,
              ui_host: "https://us.posthog.com",
              autocapture: false,
              capture_pageview: false,
              capture_pageleave: false,
              capture_performance: false,
              capture_exceptions: false,
              capture_heatmaps: false,
              capture_dead_clicks: false,
              rageclick: false,
              disable_session_recording: true,
              disable_surveys: true,
              disable_product_tours: true,
              disable_external_dependency_loading: true,
              advanced_disable_flags: true,
              person_profiles: "never",
              respect_dnt: true,
              opt_out_capturing_by_default: false,
              opt_out_persistence_by_default: false,
              persistence: "localStorage",
              persistence_name: "common-practice-analytics",
              before_send: sanitiseBrowserCapture,
            });
            // The pinned SDK only resumes its paused send queue through opt-in.
            // Suppress that event and immediately remove its permission flag,
            // so the removed controls leave no stored consent choice.
            active.opt_in_capturing({ captureEventName: false });
            active.clear_opt_in_out_capturing();
          },
          catch: () => new AnalyticsError({ operation: "configure", reason: "unavailable" }),
        });
      }).pipe(Effect.onError(stop), Effect.ignore);
      return BrowserAnalytics.of({
        recordPageView: Effect.fn("BrowserAnalytics.recordPageView")((input) =>
          Effect.gen(function* () {
            const page = yield* Schema.encodeEffect(PageView)(input).pipe(
              Effect.mapError(
                () => new AnalyticsError({ operation: "page-view", reason: "invalid-data" }),
              ),
            );
            const active = yield* Ref.get(client);
            const last = yield* Ref.get(sentPage);
            if (
              Option.isNone(active) ||
              Option.exists(last, (value) => value.page === input.page)
            ) {
              return;
            }
            if (
              Option.isNone(config) ||
              !Schema.is(CaptureConfig.cases.AnalyticsEnabled)(config.value)
            ) {
              return;
            }
            const capture = config.value;
            const result = yield* Effect.try({
              try: () =>
                active.value.capture("common_practice_page_viewed", {
                  ...page,
                  ...source,
                  environment: capture.environment,
                  stage: capture.stage,
                  $process_person_profile: false,
                  $geoip_disable: true,
                }),
              catch: () => new AnalyticsError({ operation: "page-view", reason: "unavailable" }),
            });
            const accepted = yield* Schema.decodeUnknownEffect(CaptureAcknowledgement)(result).pipe(
              Effect.mapError(
                () => new AnalyticsError({ operation: "page-view", reason: "invalid-data" }),
              ),
            );
            if (Option.isSome(accepted)) {
              yield* Ref.set(sentPage, Option.some(input));
            }
          }).pipe(lock.withPermits(1)),
        ),
        recordNavigation: Effect.fn("BrowserAnalytics.recordNavigation")((input) =>
          Effect.gen(function* () {
            const navigation = yield* Schema.encodeEffect(NavigationUse)(input).pipe(
              Effect.mapError(
                () => new AnalyticsError({ operation: "navigation", reason: "invalid-data" }),
              ),
            );
            const active = yield* Ref.get(client);
            if (
              Option.isNone(active) ||
              Option.isNone(config) ||
              !Schema.is(CaptureConfig.cases.AnalyticsEnabled)(config.value)
            ) {
              return;
            }
            const capture = config.value;
            const result = yield* Effect.try({
              try: () =>
                active.value.capture("common_practice_navigation_used", {
                  ...navigation,
                  ...source,
                  environment: capture.environment,
                  stage: capture.stage,
                  $process_person_profile: false,
                  $geoip_disable: true,
                }),
              catch: () => new AnalyticsError({ operation: "navigation", reason: "unavailable" }),
            });
            yield* Schema.decodeUnknownEffect(CaptureAcknowledgement)(result).pipe(
              Effect.mapError(
                () => new AnalyticsError({ operation: "navigation", reason: "invalid-data" }),
              ),
            );

