import * as Axiom from "alchemy/Axiom";
import * as Output from "alchemy/Output";
import { retain } from "alchemy/RemovalPolicy";
import * as Effect from "effect/Effect";
import { commonPracticeDashboardDefinitions } from "./dashboards";
import type { CommonPracticeDashboardDatasets } from "./dashboards/types";

export { CommonPracticeObservability } from "../stacks/observability";

/**
 * Site owns the three physical datasets; Common Practice owns only its scoped token and
 * dashboards. The live Website binds the token, so it is retained like the
 * dashboards: removing the declaration or destroying this stack must not cut
 * off production telemetry. A replaced token leaves its old generation in
 * Axiom for deliberate revocation.
 */
export const declareCommonPracticeAxiomResources = Effect.fn(
  "Axiom.declareCommonPracticeResources",
)(function* (datasets: CommonPracticeDashboardDatasets) {
  const ingest = yield* Axiom.ApiToken("DawTelemetryIngest", {
    name: "common-practice-telemetry-ingest",
    description: "Ingest Common Practice Effect telemetry only; renamed 3 October 2026",
    datasetCapabilities: {
      [datasets.logsDataset]: { ingest: ["create"] },
      [datasets.tracesDataset]: { ingest: ["create"] },
      [datasets.metricsDataset]: { ingest: ["create"] },
    },
  }).pipe(retain());

  const definitions = commonPracticeDashboardDefinitions(datasets);
  for (const definition of definitions) {
    yield* Axiom.Dashboard(definition.logicalId, {
      uid: definition.uid,
      // Alchemy's public Chart model is readonly while its provider input
      // currently requires mutable SDK arrays. Alchemy resolves the typed
      // document at plan time without changing its JSON value.
      dashboard: Output.asOutput(definition.dashboard).as<Axiom.DashboardProps["dashboard"]>(),
      overwrite: true,
    }).pipe(retain());
  }

  return { ingest, dashboardCount: definitions.length };
});
import * as Axiom from "alchemy/Axiom";
import * as Cloudflare from "alchemy/Cloudflare";
import { Stack } from "alchemy/Stack";
import * as Config from "effect/Config";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";
import { productionStage } from "./addresses";

/**
 * The providers and state both telemetry stacks (`daw-observability` and
 * `daw-trace-export`) run with. Both provider Layers read HttpClient from
 * StackServices (alchemy/Stack.ts), so neither depends on the other's output. This is
 * Alchemy's documented composition, and the diagnostic sees a dependency that is not one.
 */
export const telemetryStackProps = {
  // @effect-diagnostics-next-line layerMergeAllWithDependencies:off
  providers: Layer.mergeAll(Cloudflare.providers(), Axiom.providers()),
  state: Cloudflare.state(),
};

/** Both telemetry stacks are production-only: the live Website depends on their resources. */
export const requireProductionStage = Effect.gen(function* () {
  const stack = yield* Stack;
  // oxlint-disable-next-line effect/no-schema-decoder-outside-ingress -- Alchemy supplies this raw CLI stage at the stack entrypoint.
  yield* Schema.decodeUnknownEffect(Schema.Literal(productionStage))(stack.stage).pipe(
    Effect.mapError((cause) => new Config.ConfigError(cause)),
  );
});
import * as Axiom from "alchemy/Axiom";
import * as Output from "alchemy/Output";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import { projectName } from "../observability/names";
import { commonPracticeObservabilityProduction, siteProduction } from "../stacks/addresses";

/**
 * Website.Vite is the deployed Worker, and it has no Effect runtime context for
 * `Axiom.Telemetry` to bind into. Bind the standard OTLP log variables that
 * Alchemy's Worker runtime reads, plus the Protobuf metrics exporter's values,
 * directly on that outer host. Redacted values upload as `secret_text`.
 */
export const commonPracticeTelemetryBindings = Effect.fn("Axiom.commonPracticeTelemetryBindings")(
  function* () {
    const token = yield* Axiom.ApiToken.ref(
      "DawTelemetryIngest",
      commonPracticeObservabilityProduction,
    );
    const logs = yield* Axiom.Dataset.ref("SiteProdLogsDataset", siteProduction);
    const metrics = yield* Axiom.Dataset.ref("SiteProdMetricsDataset", siteProduction);

    return {
      OTEL_SERVICE_NAME: projectName,
      OTEL_EXPORTER_OTLP_LOGS_ENDPOINT: logs.otelLogsEndpoint,
      OTEL_EXPORTER_OTLP_LOGS_HEADERS: Output.all(token.token, logs.name).pipe(
        // oxlint-disable-next-line effect/no-native-array-methods -- Alchemy Output.map resolves deferred resource values; this is not Array.map.
        Output.map(([bearer, name]) =>
          Redacted.make(
            `Authorization=${encodeURIComponent(`Bearer ${Redacted.value(bearer)}`)},X-Axiom-Dataset=${encodeURIComponent(name)}`,
          ),
        ),
      ),
      COMMON_PRACTICE_AXIOM_METRICS_ENDPOINT: metrics.otelMetricsEndpoint,
      COMMON_PRACTICE_AXIOM_METRICS_TOKEN: token.token,
      COMMON_PRACTICE_AXIOM_METRICS_DATASET: metrics.name,
    };
  },
);

