import * as Layer from "effect/Layer";
import * as Match from "effect/Match";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";
import * as Stream from "effect/Stream";
import * as Headers from "effect/unstable/http/Headers";
import * as HttpClient from "effect/unstable/http/HttpClient";
import * as HttpClientRequest from "effect/unstable/http/HttpClientRequest";
import { readCaptureBytes } from "./body.ingress";
import { CaptureRelayError } from "./errors";
import { CaptureBatch, CaptureResponse, CaptureResponseMediaType, RetryAfter } from "./schemas";
import { CaptureRelay } from "./service";

// This private HTTP adapter owns checked provider input and output. No Promise bridge.
export const CaptureRelayLive = Layer.effect(
  CaptureRelay,
  Effect.gen(function* () {
    const http = yield* HttpClient.HttpClient;
    return CaptureRelay.of({
      forwardBatch: Effect.fn("CaptureRelay.forwardBatch")(
        function* (input) {
          const batch = yield* Schema.encodeEffect(CaptureBatch)(input).pipe(
            Effect.mapError(() => new CaptureRelayError({ reason: "invalid-request" })),
          );
          // Rebuild the allowed fields; caller cookies, IP, auth and traces are excluded.
          const request = HttpClientRequest.post("https://us.i.posthog.com/e/").pipe(
            HttpClientRequest.setUrlParams(batch.query),
            HttpClientRequest.bodyUint8Array(batch.body, batch.contentType),
          );
          const response = yield* http
            .execute(request)
            .pipe(Effect.mapError(() => new CaptureRelayError({ reason: "transport" })));
          if (response.status >= 300 && response.status < 400) {
            return yield* new CaptureRelayError({ reason: "redirect" });
          }
          const stream = response.stream.pipe(
            Stream.catchTag("HttpClientError", (failure) =>
              Match.value(failure.reason).pipe(
                Match.tag("EmptyBodyError", () => Stream.empty),
                Match.orElse(() => Stream.fail(new CaptureRelayError({ reason: "transport" }))),
              ),
            ),
          );
          const body = yield* readCaptureBytes({ stream, oversized: "response-too-large" });
          const retryAfter = yield* Option.match(Headers.get(response.headers, "retry-after"), {
            onNone: () => Effect.succeedNone,
            onSome: (value) => Schema.decodeEffect(RetryAfter)(value).pipe(Effect.option),
          });
          const contentType = yield* Option.match(Headers.get(response.headers, "content-type"), {
            onNone: () => Effect.succeedNone,
            onSome: (value) =>
              Schema.decodeEffect(CaptureResponseMediaType)(value.toLowerCase()).pipe(
                Effect.option,
              ),
          });
          return yield* Schema.decodeEffect(CaptureResponse)({
            status: response.status,
            body,
            retryAfter,
            contentType,
          }).pipe(Effect.mapError(() => new CaptureRelayError({ reason: "transport" })));
        },
        Effect.provideService(HttpClient.TracerPropagationEnabled, false),
        Effect.scoped,
      ),
    });
  }),
);
import { ApiStatusCode } from "@common-practice/analytics/schemas";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";

export const captureByteLimit = 1024 * 1024;
export const CaptureBytes = Schema.Uint8Array.check(
  Schema.makeFilter((bytes) => bytes.byteLength <= captureByteLimit),
).pipe(Schema.brand("CaptureRelayBytes"));
export const CaptureMediaType = Schema.String.check(
  Schema.isPattern(
    /^(?:text\/plain|application\/json|application\/x-www-form-urlencoded)(?:;\s*charset=utf-8)?$/u,
  ),
).pipe(Schema.brand("CaptureRelayMediaType"));
const RetryCount = Schema.String.check(Schema.isPattern(/^(?:[1-9]|10)$/u)).pipe(
  Schema.brand("CaptureRelayRetryCount"),
);
// Missing wire keys become Option values; encoding removes None keys again.
export const CaptureQuery = Schema.Struct({
  compression: Schema.OptionFromOptionalKey(Schema.Literal("base64")),
  retry_count: Schema.OptionFromOptionalKey(RetryCount),
});
export const CaptureBatch = Schema.Struct({
  body: CaptureBytes,
  contentType: CaptureMediaType,
  query: CaptureQuery,
}).check(
  Schema.makeFilter((input) =>
    Option.match(input.query.compression, {
      onNone: () => true,
      onSome: () => input.contentType.startsWith("application/x-www-form-urlencoded"),
    }),
  ),
);
export type CaptureBatch = typeof CaptureBatch.Type;
export const RetryAfter = Schema.String.check(Schema.isPattern(/^[0-9]{1,7}$/u)).pipe(
  Schema.brand("CaptureRelayRetryAfter"),
);
export const CaptureResponseMediaType = Schema.String.check(
  Schema.isPattern(/^(?:application\/json|text\/plain)(?:;\s*charset=utf-8)?$/u),
).pipe(Schema.brand("CaptureRelayResponseMediaType"));
export const CaptureResponse = Schema.Struct({
  status: ApiStatusCode,
  body: CaptureBytes,
  retryAfter: Schema.Option(RetryAfter),
  contentType: Schema.Option(CaptureResponseMediaType),
});
export type CaptureResponse = typeof CaptureResponse.Type;
"}}

