import takumiModule from "@takumi-rs/wasm/auto";
import * as Effect from "effect/Effect";
import * as Encoding from "effect/Encoding";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";
import { render } from "takumi-js";
import type { Page } from "@common-practice/content/schemas";
import { pageImage } from "./image";
import { ImageRenderError } from "@common-practice/content/errors";
import { PngBytes } from "@common-practice/content/schemas";
import { PageRenderer } from "@common-practice/content/service";

export const PageRendererLive = Layer.succeed(
  PageRenderer,
  PageRenderer.of({
    renderPage: Effect.fn("PageRenderer.renderPage")(function* (page: Page) {
      const font = yield* Encoding.decodeBase64(fontBase64).pipe(
        Effect.fromResult,
        Effect.mapError(() => new ImageRenderError({ reason: "font" })),
      );
      const image = pageImage(page);
      // The unavoidable SDK Promise stays private; interruption aborts Takumi's host call.
      const bytes = yield* Effect.tryPromise<unknown, ImageRenderError>({
        try: (signal) =>
          render(image, {
            module: takumiModule,
            width: 1200,
            height: 630,
            format: "png",
            fonts: [{ name: "Common Practice", data: font }],
            emoji: "from-font",
            signal,
          }),
        catch: () => new ImageRenderError({ reason: "render" }),
      });
      return yield* Schema.decodeUnknownEffect(PngBytes)(bytes).pipe(
        Effect.mapError(() => new ImageRenderError({ reason: "output" })),
      );
    }),
  }),
);
