import type { DeploymentStage } from "../../schemas";
import type { IsolateRequest } from "../isolate-identity";
import { requestEventName, projectName } from "../../observability/names";
import { classifyMethod, classifyTraffic, classifyAiBot, statusGroup } from "./classification";
import { RequestObservationEvent } from "./schemas";
import type { RequestSurface, RouteFamily } from "./schemas";
import { RequestObservationError } from "./errors";

export interface RequestObservationInput {
  readonly request: HttpServerRequest.HttpServerRequest;
  readonly stage: DeploymentStage;
  readonly surface: RequestSurface;
  readonly routeFamily: RouteFamily;
  readonly isolate: IsolateRequest;
  readonly worker: Option.Option<"website" | "backend">;
}

// Build only fixed labels, then check the complete outgoing log record.
export const encodeRequestObservation = Effect.fnUntraced(function* <E>({
  input,
  exit,
}: {
  readonly input: RequestObservationInput;
  readonly exit: Exit.Exit<{ readonly status: number }, E>;
}) {
  const userAgent = Headers.get(input.request.headers, "user-agent");
  const status = Exit.match(exit, {
    onFailure: () => Option.none<number>(),
    onSuccess: (response) => Option.some(response.status),
  });
  const event: RequestObservationEvent = {
    event: requestEventName,
    project: projectName,
    stage: input.stage,
    surface: input.surface,
    routeFamily: input.routeFamily,
    method: classifyMethod(input.request.method),
    outcome: Exit.match(exit, {
      onFailure: (cause) =>
        Boolean.match(Cause.hasInterrupts(cause), {
          onFalse: () => "failed",
          onTrue: () => "cancelled",
        }),
      onSuccess: () => "completed",
    }),
    statusGroup: statusGroup(status),
    requestSeq: input.isolate.requestSeq,
    trafficCategory: classifyTraffic(userAgent),
    aiBot: classifyAiBot(userAgent),
    ...Option.match(input.worker, {
      onNone: () => ({}),
      onSome: (worker) => ({ worker }),
    }),
  };
  // Leave a key out when it has no value, so no log field is undefined.
  const withIsolate = Option.match(input.isolate.isolateId, {
    onNone: () => event,
    onSome: (isolateId) => ({ ...event, isolateId }),
  });
  const complete = Option.match(status, {
    onNone: () => withIsolate,
    onSome: (responseStatus) => ({ ...withIsolate, status: responseStatus }),
  });
  return yield* Schema.encodeEffect(RequestObservationEvent)(complete).pipe(
    Effect.mapError(() => new RequestObservationError({ reason: "invalid-event" })),
  );
});

