// Only this exact prefix migration is allowed; project and resource identity must match.
const matchesOwnedMarker = (
  expected: typeof OwnershipMarker.Type,
  observed: typeof OwnershipMarker.Type,
): boolean =>
  expected === observed ||
  expected === observed.replace(/^daw-alchemy:/u, "common-practice-alchemy:");

export const requirePostHogOwnership = Effect.fn("PostHog.requireOwnership")(function* (
  input: Readonly<{ expected: typeof OwnershipMarker.Type; observed: typeof OwnershipMarker.Type }>,
) {
  if (matchesOwnedMarker(input.expected, input.observed)) {
    return;
  }
  return yield* new PostHogManagementError({
    operation: "read-project",
    reason: "foreign-resource",
  });
});

export const PostHogProjectProvider = Provider.effect(
  PostHogProject,
  Effect.gen(function* () {
    const management = yield* PostHogManagement;
    return {
      stables: ["id", "organisation"],
      nuke: { skip: true },
      list: () => Effect.succeed([]),
      diff: Effect.fn("PostHogProject.diff")(function* ({ olds, news }) {
        if (!Diff.isResolved(news)) {
          return;
        }
        const previous = Option.fromNullishOr(olds);
        if (
          Option.isSome(previous) &&
          (previous.value.organisation !== news.organisation ||
            !matchesOwnedMarker(news.marker, previous.value.marker))
        ) {
          return yield* new PostHogManagementError({
            operation: "save-project",
            reason: "replacement-refused",
          });
        }
      }),
      read: Effect.fn("PostHogProject.read")(function* ({ olds, output }) {
        const state = Option.fromNullishOr(output);
        if (Option.isNone(state)) {
          return;
        }
        const current = yield* management.readProject(state.value).pipe(
          Effect.flatMap(Effect.fromOption),
          Effect.mapError(
            () =>
              new PostHogManagementError({
                operation: "read-project",
                reason: "replacement-refused",
              }),
          ),
        );
        yield* requirePostHogOwnership({ expected: olds.marker, observed: current.marker });
        if (current.organisation !== olds.organisation) {
          return yield* new PostHogManagementError({
            operation: "read-project",
            reason: "foreign-resource",
          });
        }
        return current;
      }),
      reconcile: Effect.fn("PostHogProject.reconcile")(function* ({ news, output }) {
        const state = Option.fromNullishOr(output);
        const observed = yield* Option.match(state, {
          onNone: () => management.findProject(news),
          onSome: (current) => management.readProject(current),
        });
        if (Option.isNone(observed)) {
          if (Option.isSome(state)) {
            return yield* new PostHogManagementError({
              operation: "save-project",
              reason: "replacement-refused",
            });
          }
          return yield* management.createProject(news);
        }
        yield* requirePostHogOwnership({ expected: news.marker, observed: observed.value.marker });
