          return yield* new PostHogManagementError({
            operation: "save-project",
            reason: "foreign-resource",
          });
        }
        return yield* management.updateProject({ ...observed.value, ...news });
      }),
      delete: Effect.fn("PostHogProject.delete")(() =>
        Effect.fail(
          new PostHogManagementError({ operation: "save-project", reason: "retained-project" }),
        ),
      ),
    };
  }),
);

