    const findProject = Effect.fn("PostHogManagement.findProject")(function* (
      input: ProjectDefinition,
    ) {
      const desired = yield* Schema.encodeEffect(ProjectDefinition)(input).pipe(
        Effect.mapError(
          () => new PostHogManagementError({ operation: "list-projects", reason: "invalid-data" }),
        ),
      );
      const found = yield* Stream.paginate(0, (offset) =>
        Effect.gen(function* () {
          if (offset > 10_000) {
            return yield* new PostHogManagementError({
              operation: "list-projects",
              reason: "pagination",
            });
          }
          const result = yield* projects
            .list({ organization_id: desired.organisation, limit: 100, offset })
            .pipe(
              Effect.timeout("20 seconds"),
              Effect.mapError(
                () =>
                  new PostHogManagementError({ operation: "list-projects", reason: "provider" }),
              ),
            );
          const page = yield* Schema.decodeUnknownEffect(ProjectPage)(result).pipe(
            Effect.mapError(
              () =>
                new PostHogManagementError({ operation: "list-projects", reason: "invalid-data" }),
            ),
          );
          const more = Option.isSome(Option.flatten(Option.fromNullishOr(page.next)));
          if (more && Array.isReadonlyArrayEmpty(page.results)) {
            return yield* new PostHogManagementError({
              operation: "list-projects",
              reason: "pagination",
            });
          }
          return [
            Function.pipe(
              page.results,
              Array.filter((item) => item.name.toLowerCase() === desired.name.toLowerCase()),
              Array.map((item) => item.id),
            ),
            Boolean.match(more, {
              onTrue: () => Option.some(offset + page.results.length),
              onFalse: () => Option.none<number>(),
            }),
          ] satisfies readonly [readonly (typeof ProjectId.Type)[], Option.Option<number>];
        }),
      ).pipe(Stream.runCollect);
      if (found.length > 1) {
        return yield* new PostHogManagementError({
          operation: "list-projects",
          reason: "ambiguous-create",
        });
      }
      return yield* Option.match(Array.head(found), {
        onNone: () => Effect.succeedNone,
        onSome: (id) => readProject({ organisation: input.organisation, id }),
      });
